-- The table each paid line came from (D160 §2; ticket #542): one payment can now cover lines of several
-- tables of a linked group, so a line records its own table. The worker isolates each table's lines on
-- their own, and an undo puts a line back on its table.
-- Generated by drizzle-kit, then edited by hand: the column is added nullable, backfilled, then made
-- NOT NULL, inside the row-level-security steps. One transaction:
--   0. `payments` and `payment_lines` stop forcing row-level security on their owner for the length of
--      this transaction, and `payment_lines` stops touching `updated_at` (same reasons as 0040): the
--      backfill must see every row and change nothing else;
--   1. `payment_lines.table_id`, nullable for now;
--   2. the backfill: every payment so far covers one table, so each line takes its payment's table;
--   3. NOT NULL, the foreign key to the venue's tables, and the index for the open lines of a table;
--   4. back to normal: the trigger and forced row-level security again.
-- Privileges are unchanged (src/table-access.ts): the app role already inserts and reads these rows.

-- 0. Owner access for the backfill; undone at step 4.
ALTER TABLE "restro"."payments" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" DISABLE TRIGGER "payment_lines_touch_updated_at";--> statement-breakpoint

-- 1. The column.
ALTER TABLE "restro"."payment_lines" ADD COLUMN "table_id" text;--> statement-breakpoint

-- 2. Backfill: a line is on its payment's table.
UPDATE "restro"."payment_lines" AS "line" SET "table_id" = "payment"."table_id" FROM "restro"."payments" AS "payment" WHERE "payment"."tenant_id" = "line"."tenant_id" AND "payment"."id" = "line"."payment_id";--> statement-breakpoint

-- 3. Required from now on, a real table of the tenant, and indexed for "being paid" per table.
ALTER TABLE "restro"."payment_lines" ALTER COLUMN "table_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" ADD CONSTRAINT "payment_lines_table_fk" FOREIGN KEY ("tenant_id","table_id") REFERENCES "restro"."tables"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "payment_lines_open_table_idx" ON "restro"."payment_lines" USING btree ("tenant_id","table_id") WHERE "restro"."payment_lines"."open";--> statement-breakpoint

-- 4. Back to normal.
ALTER TABLE "restro"."payment_lines" ENABLE TRIGGER "payment_lines_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."payments" FORCE ROW LEVEL SECURITY;
